if not ZS or(_S and not VS.won)or(ZS and not _S and VS.won)then
local aT,bT=pcall(gb.styleP,VS)
WS,XS=(aT and tonumber(bT))or tonumber(VS.p),W.IC.SIM_W
end
end
return(US*2+WS*XS)/(TS+2+XS)
end
