Jab[Lab]=hb.have(Lab)
end
local Oab=math.min(Jab[Lab],Mab)
Jab[Lab]=Jab[Lab]-Oab
local Pab=Mab-Oab
if Pab<=0 then
return
end
local Qab=N.Items[Lab]
local Rab=hb.sources()[Lab]
if Nab<3 and type(Qab)==G0e[2452]and type(Qab.crafting_recipe)==G0e[2452]and not(Rab and Rab[1])then
Hab[Lab]=(Hab[Lab]or 0)+Pab
Iab=Iab+(tonumber(Qab.crafting_cost)or 0)*Pab
for Sab,Uab in pairs(Qab.crafting_recipe)do
Kab(Sab,(tonumber(Uab)or 0)*Pab,Nab+1)
end
else
Gab[Lab]=(Gab[Lab]or 0)+Pab
end
end
for Vab,Wab in pairs(type(Fab)==G0e[2452]and Fab.crafting_recipe or{})do
Kab(Vab,tonumber(Wab)or 0,0)
end
return Gab,Hab,Iab
end
function hb.relicSources(Xab)
