if lcb==qcb.id or(ycb>Bcb and#wcb==0 and(not ncb or zcb>ncb))then
mcb,ncb=Acb,zcb
end
end
end
if ocb and mcb and mcb~=ocb and(tonumber(mcb.score)or 0)<(tonumber(ocb.score)or 0)*1.5 then
mcb=ocb
end
kcb.target=mcb and mcb.id or nil
if not mcb then
kcb.name,kcb.runs,kcb.gain,kcb.where,kcb.gold,kcb.nosrc,kcb.ready=nil,nil,nil,nil,nil,nil,nil
