kcb.items[Kcb]=(tonumber(O.relicValue)or 3000)*(Gcb/Ccb)/Gcb*Mcb/Lcb.per
kcb.need[Kcb]=mcb.miss[Kcb]
end
end
if Gcb>Ecb then
Dcb,Ecb=Fcb,Gcb
end
end
kcb.name,kcb.runs,kcb.gain,kcb.where,kcb.gold,kcb.nosrc=mcb.name,mcb.runs,mcb.gain,Dcb,mcb.gold,#mcb.nosrc>0 and mcb.nosrc or nil
kcb.ready=next(mcb.miss)==nil
kcb.crafts=mcb.crafts
