return F.status(G0e[3760],G0e[3761])
end
local orb=N.session()
if not orb then
return
end
local prb={}
for qrb,rrb in ipairs(P.goals or{})do
table.insert(prb,rrb)
end
table.sort(prb,function(srb,trb)
return(srb.gain or 0)>(trb.gain or 0)
end)
local urb={}
for vrb,wrb in ipairs(V.equipped())do
urb[wrb.uuid]=true
end
local xrb,yrb,zrb={},0,{}
for Arb,Brb in ipairs(prb)do
if Brb.pinned then
for Crb,Drb in ipairs(Brb.items or{})do
xrb[Drb.id]=(xrb[Drb.id]or 0)+Drb.amount
end
end
end
for Erb,Frb in ipairs(prb)do
local Grb,Hrb
if Frb.ready and not Frb.pinned and yrb<2 and(ab.evoBlocked[Frb.uuid]or 0)<os.time()then
if Frb.hidden and(Frb.tierRank or 0)<hb.TIER_RANK.S then
Grb=G0e[3762]
end
for Irb,Jrb in ipairs(Grb and{}or Frb.items or{})do
if hb.have(Jrb.id)-Jrb.amount<(xrb[Jrb.id]or 0)then
Grb=string.format(G0e[3763],(N.Items[Jrb.id]or{}).name or Jrb.id)
break
end
end
Grb=Grb or ab.evoEats(Frb,urb)
if not Grb then
local Krb,Lrb=ab.evolve(Frb,G0e[3764]..(#(Frb.eats or{})>0 and G0e[3765]or G0e[1368]))
if Krb then
yrb,Hrb=yrb+1,true
table.insert(zrb,G0e[3664]..V.name(Frb.from)..G0e[3766]..V.name(Frb.to))
else
ab.evoBlocked[Frb.uuid]=os.time()+3600
Grb=Lrb
end
end
if Grb then
table.insert(zrb,V.name(Frb.from)..G0e[2810]..Grb)
end
end
if not Hrb then
for Mrb,Nrb in ipairs(Frb.items or{})do
xrb[Nrb.id]=(xrb[Nrb.id]or 0)+Nrb.amount
end
end
end
F.status(G0e[3760],#zrb>0 and table.concat(zrb,G0e[2843])or G0e[3767])
end
ib.BONUS=1.5
ib.SLOW=1.4
function ib.boost(Orb,Prb,Qrb,Rrb)
if Prb<2 or Qrb>=math.min(O.dangerReach,(Rrb or 1)*0.9)then
return
end
local Srb=Qrb<math.min(O.safeReach,(Rrb or 1)*0.75)
local Trb=0
for Urb,Vrb in ipairs(Orb)do
if not Vrb.farm and not Vrb.train and Vrb.cost>0 then
Trb=math.max(Trb,Vrb.gain/Vrb.cost)
end
end
for Wrb,Xrb in ipairs(Orb)do
if Xrb.train==G0e[3768]or(Xrb.train==G0e[3769]and Srb)then
Xrb.gain=math.max(Xrb.gain,Trb*Xrb.cost*1.05)
end
end
end
ib.HOLD_REACH=0.3
ib.ZONE=0.25
function ib.hold(Yrb,Zrb,_rb)
if Zrb<2 or Yrb>=ib.HOLD_REACH+(_rb and 0.1 or 0)then
return false
end
return true,string.format(G0e[3770],math.floor(Yrb*100+0.5))
end
function ib.same(asb,bsb)
if#asb~= #bsb then
return false
end
local csb={}
for dsb,esb in ipairs(asb)do
csb[esb]=true
end
for fsb,gsb in ipairs(bsb)do
if not csb[gsb]then
return false
end
end
return true
end
function ib.team()
local hsb={}
for isb,jsb in ipairs(V.equipped())do
table.insert(hsb,jsb.uuid)
end
return hsb
end
function ib.target()
local ksb=N.session()
if not ksb then
return nil
end
local lsb,msb
local nsb=O.autoEvolve and O.evolveUnit~=G0e[1368]and O.evolveUnit or nil
for osb,psb in ipairs(P.goals or{})do
local qsb,rsb=nil,0
for ssb,tsb in ipairs(psb.plans or{})do
if tsb.takedown then
qsb=tsb
else
rsb=rsb+1
end
end
local usb=qsb and psb.intoTeam and(psb.pinned or not psb.unknown)and(not nsb or psb.uuid==nsb)and ksb.collection:get_unit_by_uuid(psb.uuid)
if usb then
local vsb=tonumber(qsb.what==G0e[3126]and usb.total_kills or usb.total_takedowns)or 0
if vsb<qsb.need then
local wsb=(rsb==0 and 1000 or 0)+(tonumber(psb.tierRank)or 0)*10-osb*0.01
if not lsb or wsb>msb then
lsb,msb={uuid=psb.uuid,id=psb.from,to=psb.to,what=qsb.what,have=vsb,need=qsb.need},wsb
end
end
end
end
return lsb
end
function ib.realHave(xsb)
local ysb=N.session()
local zsb=ysb and ysb.collection:get_unit_by_uuid(xsb.uuid)
local Asb=zsb and tonumber(xsb.what==G0e[3126]and zsb.total_kills or zsb.total_takedowns)or 0
return math.max(Asb,xsb.have+(xsb.got or 0))
