function ib.now()
if ib._at and U.now()-ib._at<10 then
return ib._t,ib._base
end
local Bsb=(P.train.on and P.train.on.base)or ib.team()
local Csb=table.clone(Bsb)
table.sort(Csb)
ib._t,ib._base,ib._at=ib.target(),table.concat(Csb,G0e[3162]),U.now()
