function ib.valueFor(Dsb)
if not(O.trainTakedowns and O.goals)then
return 0,1
end
local Esb=P.trainSim[Dsb.key]
if not(Esb and Esb.ok and os.time()-(Esb.at or 0)<6*3600)then
return 0,1
end
