local Hsb={}
for Isb,Jsb in ipairs(P.savedTeam or{})do
Hsb[Isb]=Jsb
end
table.sort(Hsb)
if not(Fsb and Esb.uuid==Fsb.uuid and(Esb.base==Gsb or Esb.base==table.concat(Hsb,G0e[3162])))or not ib.eligible(Dsb)then
return 0,1
end
local Ksb=ib.perRun(Dsb.key,Fsb.id)or 0
