function ib.scan()
local Msb=O.trainTakedowns and O.sim and ib.now()
if not Msb then
return
end
local Nsb=(P.train.on and P.train.on.base)or ib.team()
for Osb,Psb in ipairs(Nsb)do
if Psb==Msb.uuid then
return
end
end
local Qsb,Rsb=0,0
for Ssb,Tsb in ipairs(W.lastScored or{})do
if Qsb>=3 or Rsb>=2 then
