end
if ib.eligible(Tsb)then
local Usb=P.trainSim[Tsb.key]
local Vsb=Usb and Usb.uuid==Msb.uuid and os.time()-(Usb.at or 0)<6*3600
local Wsb=ib.plan(Tsb,Msb,Nsb)
if not Vsb then
Rsb=Rsb+1
end
if Wsb.ok then
Qsb=Qsb+1
end
end
end
local Xsb=ib.bestInfinite()
if Xsb then
ib.plan(Xsb,Msb,Nsb)
end
end
function ib.bestInfinite()
local Ysb,Zsb
for _sb,atb in ipairs(W.lastScored or{})do
if atb.kind==G0e[2477]and ib.eligible(atb)then
local btb,ctb=P.train.real[atb.key],atb.rec or W.rec(atb.key)
local dtb=(tonumber(ctb.timed)or 0)>0 and ctb.sec/ctb.timed/60 or 0
local etb=(btb and btb.n>0 and dtb>0)and(btb.sum/btb.n)/dtb or 0
if etb<=0 then
etb=db.hiveTrainRate(atb.key)or 0
end
if etb>(Zsb or 0)then
Ysb,Zsb=atb,etb
end
end
end
return Ysb
end
function ib.ratio()
local ftb=P.train.cal
if not(ftb and(ftb.n or 0)>0 and(ftb.sim or 0)>0)then
return 1
end
return U.clamp(ftb.real/ftb.sim,0.05,2)
end
function ib.perRun(gtb,htb)
local itb=P.train.real[gtb]
if itb and itb.n>0 then
return itb.sum/itb.n,true
end
local jtb=db.hiveTrain(gtb,htb)
if jtb then
return jtb,true
end
local ktb,ltb=0,0
local mtb=W.isInf(gtb)
for ntb,otb in pairs(P.train.real)do
if W.isInf(ntb)==mtb then
ktb,ltb=ktb+otb.sum,ltb+otb.n
end
end
if ltb>0 then
return ktb/ltb,true
end
local ptb=P.trainSim[gtb]
return ptb and ptb.tk and ptb.tk*ib.ratio()or nil,false
end
function ib.eligible(qtb)
if qtb.kind==G0e[2919]or qtb.kind==G0e[2472]then
return false,G0e[3771]
end
if qtb.kind==G0e[2478]then
return false,G0e[3772]
end
if qtb.kind==G0e[2922]then
return false,G0e[3773]
end
