return false,G0e[3774]
end
if N.Levels[qtb.level]and N.Levels[qtb.level]._randomequippedmode then
return false,G0e[3775]
end
if(P.train.bad[qtb.key]or 0)>os.time()then
return false,G0e[3776]..os.date(G0e[3658],P.train.bad[qtb.key])
end
local rtb=qtb.rec or W.rec(qtb.key)
if rtb.runs>=3 and rtb.wins/rtb.runs<0.8 then
return false,G0e[3777]
end
local stb=P.simRes[qtb.key]
if stb and stb.trust and not stb.trust.ok then
return false,G0e[3778]
end
return true
end
function ib.plan(ttb,utb,vtb)
local wtb=N.session()
local xtb=table.clone(vtb)
table.sort(xtb)
local ytb=table.concat(xtb,G0e[3162])
local ztb=(tonumber((P.simCal[ttb.key]or{}).n)or 0)>0
local Atb=ztb and 1.3 or 2
local Btb=ytb..G0e[2782]..utb.uuid..(ztb and G0e[3779]or G0e[3780])..G0e[3781]
local Ctb=P.trainSim[ttb.key]
if Ctb and Ctb.sig==Btb and not Ctb.pending and os.time()-(Ctb.at or 0)<6*3600 then
return Ctb
end
local Dtb={sig=Btb,base=ytb,uuid=utb.uuid,at=os.time(),ok=false,margin=Atb,pending=true}
P.trainSim[ttb.key]=Dtb
local Etb,Ftb=gb.levelFor(ttb)
if ttb.ldOverride then
Etb=ttb.ldOverride
end
if not Etb then
Dtb.why,Dtb.pending=G0e[3782],nil
return Dtb
end
local Gtb=gb.info(Etb,ttb.key,Ftb,ttb.mod)
local Htb={}
for Itb,Jtb in ipairs(vtb)do
local Ktb=wtb.collection:get_unit_by_uuid(Jtb)
if Ktb then
table.insert(Htb,Ktb)
end
end
local Ltb=wtb.collection:get_unit_by_uuid(utb.uuid)
if not Ltb or#Htb==0 then
Dtb.why,Dtb.pending=G0e[3783],nil
return Dtb
end
local Mtb=gb.run(Gtb,gb.teamFrom(Htb,Gtb.map),{hpMul=1})
local Ntb=Gtb.infinite and gb.unbound(Etb)
local Otb=Ntb and W.infTier(gb.run(Gtb,gb.teamFrom(Htb,Gtb.map),{hpMul=Atb}).wave)or nil
local Ptb={}
for Qtb,Rtb in ipairs(Htb)do
if not V.isFarm(Rtb.unit_id)then
local Stb,Ttb=pcall(V.score,Rtb,ttb.mod)
table.insert(Ptb,{i=Qtb,sc=Stb and Ttb or 0})
end
end
table.sort(Ptb,function(Utb,Vtb)
return Utb.sc<Vtb.sc
end)
local Wtb
for Xtb=1,math.min(3,#Ptb)do
local Ytb=table.clone(Htb)
Ytb[Ptb[Xtb].i]=Ltb
local Ztb=gb.teamFrom(Ytb,Gtb.map)
local _tb=gb.run(Gtb,Ztb,{hpMul=Atb,train=utb.uuid})
if(Ntb and W.infTier(_tb.wave)>=Otb)or(not Ntb and _tb.won)then
local aub=gb.run(Gtb,Ztb,{hpMul=1,train=utb.uuid})
local bub=(aub.tk or 0)/math.max(0.5,aub.t/60)
if(aub.won or Ntb)and(not Wtb or bub>math.max(Wtb.rate*1.5,Wtb.rate+1))then
Wtb={out=Htb[Ptb[Xtb].i].unit_id,r=aub,rate=bub,trial=Ytb}
end
end
end
Dtb.ownMin=Mtb.t/60
if not Wtb then
Dtb.why=Ntb and string.format(G0e[3784],Otb,ztb and G0e[3785]or G0e[3786])or ztb and G0e[3787]or G0e[3788]
else
Dtb.out,Dtb.tk,Dtb.minutes=Wtb.out,Wtb.r.tk or 0,Wtb.r.t/60
Dtb.uuids={}
for cub,dub in ipairs(Wtb.trial)do
table.insert(Dtb.uuids,dub.uuid)
end
Dtb.slow=(Mtb.won and not Ntb)and Dtb.minutes/math.max(0.1,Dtb.ownMin)or 1
if Dtb.tk<=0 and next(P.train.real)==nil then
Dtb.why=G0e[3789]
elseif Dtb.slow>ib.SLOW then
Dtb.why=string.format(G0e[3790],math.floor((Dtb.slow-1)*100+0.5))
else
Dtb.ok=true
end
end
Dtb.pending=nil
F.log(1,G0e[3791],string.format(G0e[3792],ttb.label,V.name(utb.id),Dtb.out and(G0e[3793]..V.name(Dtb.out))or G0e[1368],Dtb.ok and string.format(G0e[3794],math.floor((ib.perRun(ttb.key,utb.id)or 0)+0.5),utb.what,Dtb.minutes,Dtb.ownMin)or tostring(Dtb.why)))
F.saveSoon()
return Dtb
end
function ib.home()
