if not O.autoTeam then
P.savedTeam=nil
end
return
end
if P.savedTeam and ib.same(P.savedTeam,eub.base)then
ab.restoreTeam()
else
ab.equipTeam(eub.base,G0e[3796])
end
F.log(1,G0e[3791],V.name(eub.out or G0e[2703])..G0e[3797])
