ib.home()
return F.status(G0e[3798],G0e[3799])
end
local hub=O.trainTakedowns and ib.target()or nil
if not hub then
ib.home()
return F.status(G0e[3798],O.trainTakedowns and G0e[3800]or G0e[3801])
end
local iub=V.name(hub.id)
local jub=string.format(G0e[3488],hub.what,U.fmt(hub.have),U.fmt(hub.need))
