gb.INF_CAP=80
function gb.evaluate(alc,blc)
local clc=gb.run(alc,blc,{hpMul=1})
local dlc={won=clc.won,wave=clc.wave,minutes=clc.t/60,aliveAt=clc.aliveAt,total=alc.total,at=os.time()}
if alc.infinite and gb.unbound(alc.ld)then
dlc.p=1
dlc.margin=clc.won and string.format(G0e[4408],alc.total)or(clc.timeout and alc.timeLimit and string.format(G0e[4409],math.floor(alc.timeLimit/60+0.5),clc.wave))or string.format(G0e[4410],clc.wave,clc.t/60)
elseif clc.won then
local elc=gb.run(alc,blc,{hpMul=1.3})
dlc.p=elc.won and 0.92 or 0.7
dlc.margin=elc.won and G0e[4411]or G0e[4412]
else
local flc=gb.run(alc,blc,{hpMul=0.75})
dlc.p=flc.won and 0.25 or 0.05
dlc.margin=flc.won and string.format(G0e[4413],clc.wave)or string.format(G0e[4414],clc.wave,alc.total)
if not flc.won then
local glc=gb.run(alc,blc,{hpMul=0.25})
if not glc.won then
dlc.p,dlc.hopeless=0.005,true
dlc.margin=string.format(G0e[4415],clc.wave,alc.total)
end
end
end
return dlc
end
gb.STYLE_RUNS=20
function gb.styleP(hlc,ilc)
local jlc=tonumber(hlc and hlc.p)or 0
if jlc<0.5 then
return jlc
end
ilc=ilc or((hlc.zone or hlc.style==G0e[4351])and G0e[4351]or G0e[4416])
local klc,llc=pcall(db.hiveStyle,ilc)
if not(klc and llc)then
return jlc
end
local mlc=tonumber(llc.predWin)or 0
local nlc=U.clamp((tonumber(llc.predWinWon)or 0)/math.max(1,mlc),0,1)
local olc=mlc/(mlc+gb.STYLE_RUNS)
return jlc*(1-olc*(1-nlc))
end
function gb.levelTag(plc)
if type(plc)~=G0e[2452]then
return G0e[2703]
end
if plc._gamemode==G0e[2502]or plc._infinite_tower_floor then
return G0e[4417]..tostring(plc._infinite_tower_floor or plc.floor_num or G0e[2703])
end
return tostring(plc.id or G0e[2703])..(mb.is(plc.id)and(G0e[2899]..tostring(plc.map))or G0e[1368])
end
function gb.trust(qlc,rlc)
local slc=qlc.cal or{}
if type(slc.alive)~=G0e[2452]or slc.teamSig~=gb.sig((function()
local tlc={}
for ulc,vlc in ipairs(rlc)do
table.insert(tlc,vlc.u)
end
return tlc
end)())then
return nil
end
if qlc.key==G0e[3189]and not slc.aliveLvl then
return nil
end
if slc.aliveLvl and qlc.ld and(qlc.ld.id or qlc.key==G0e[3101])and slc.aliveLvl~=gb.levelTag(qlc.ld)then
return nil
end
local wlc=gb.run(qlc,rlc,{hpMul=1})
local xlc,ylc,zlc=0,0,0
for Alc=3,math.min(wlc.wave,tonumber(slc.lastWave)or 99)do
local Blc=tonumber(slc.alive[tostring(Alc)])
local Clc=wlc.aliveAt[Alc]
if Blc and Clc and Blc>0 then
xlc=xlc+Blc
ylc=ylc+Clc
zlc=zlc+1
end
end
if zlc<2 or ylc<=0 then
return nil
end
local Dlc=xlc/ylc
return{ratio=Dlc,ok=Dlc>=0.75 and Dlc<=1.33,waves=zlc}
end
gb.GROWN_LEVEL,gb.GROWN_MIN=50,6
function gb.grownKinds()
local Elc=N.session()
local Flc,Glc={},0
for Hlc,Ilc in pairs(Elc.profile_data.collection.owned_units)do
local Jlc=Ilc.unit_id
if not Flc[Jlc]and N.Units[Jlc]and not V.isFarm(Jlc)and V.rows(Jlc)and not V.hidden(Jlc)then
local Klc,Llc=pcall(N.USC.calculate_level,Jlc,tonumber(Ilc.xp)or 0)
if Klc and(tonumber(Llc)or 0)>=gb.GROWN_LEVEL then
Flc[Jlc]=true
Glc=Glc+1
