for Slc,Tlc in pairs(Olc.profile_data.collection.owned_units)do
local Ulc=Olc.collection:get_unit_by_uuid(Tlc.uuid)or Tlc
local Vlc,Wlc=pcall(N.USC.calculate_level,Ulc.unit_id,tonumber(Ulc.xp)or 0)
