if N.Units[Ulc.unit_id]and V.rows(Ulc.unit_id)and not V.hidden(Ulc.unit_id)and Xlc then
local Ylc=V.isFarm(Ulc.unit_id)
local Zlc,_lc=pcall(Ylc and function()
return V.farm(Ulc,V.rows(Ulc.unit_id).max)
end or V.score,Ulc,Mlc)
_lc=(Zlc and _lc or 0)*(Ylc and 1 or V.skinMul(Ulc,Nlc and Nlc.skinSet)*V.eventMul(Ulc,Nlc and Nlc.ld))
local amc=Ylc and Qlc or Plc
if not amc[Ulc.unit_id]or _lc>amc[Ulc.unit_id].sc then
amc[Ulc.unit_id]={u=Ulc,sc=_lc}
end
