gb.TEAM_FASTER,gb.TEAM_FASTER_S=0.05,15
function gb.teamFaster(anc,bnc,cnc)
if anc.infinite or anc.timeLimit or type(cnc)~=G0e[2452]or not cnc.won or not tonumber(cnc.minutes)then
return nil
end
local dnc=gb.teamFrom(bnc,anc.map)
