end
function gb.zoneChoice(wnc,xnc,ync,znc)
if O.killZone==false or wnc.zone or bb.forcedWay(wnc)or(wnc.infinite and gb.unbound(wnc.ld))then
return false
end
local Anc=P.zoneRec[gb.zoneKey(wnc)]
local Bnc=Anc and(Anc.style==G0e[4351]or(Anc.style==nil and Anc.zone==true))
if Anc and Anc.won then
return Bnc==true,Bnc and G0e[4418]or nil
end
if Anc and Bnc then
return false,G0e[4419]
end
local Cnc=P.modes[wnc.key]
local Dnc=Cnc and tonumber(Cnc.streak)or 0
if not Anc and Cnc and(tonumber(Cnc.wins)or 0)>0 and Dnc==0 and wnc.key~=G0e[3189]and wnc.key~=G0e[3185]then
return false
end
local Enc=Anc~=nil or Dnc>0
local Fnc=znc and ync<=1 or(not znc and ync<=gb.ZONE_CLOSE)
if not(Enc or Fnc)then
return false
end
local Gnc=table.clone(wnc)
Gnc.zone=true
local function Hnc(Inc)
local Jnc=0
for Knc,Lnc in ipairs({0.92,1,1.08})do
Jnc=Jnc+gb.objective(gb.run(Inc,xnc,{hpMul=ync*Lnc}))
end
return Jnc/3
end
local Mnc=Hnc(Gnc)-Hnc(wnc)
if Enc and Mnc> -gb.ZONE_GAIN then
return true,G0e[4420],Mnc
end
if Fnc and Mnc>gb.ZONE_GAIN then
return true,string.format(G0e[4421],ync),Mnc
end
return false,nil,Mnc
end
function gb.strength(Nnc,Onc)
local Pnc,Qnc,Rnc,Snc,Tnc=gb.teamFrom(Onc,Nnc.map),0,0,0,0
for Unc,Vnc in ipairs(gb.LADDER)do
local Wnc,Xnc=0,0
for Ync,Znc in ipairs({0.92,1,1.08})do
local _nc=gb.run(Nnc,Pnc,{hpMul=Vnc*Znc})
if _nc.won then
Wnc=Wnc+1
end
Xnc=Xnc+_nc.wave
end
Qnc,Tnc=Qnc+Wnc,Xnc/3
if Vnc==1 then
Rnc,Snc=Wnc,Xnc/3
end
task.wait()
if Wnc==0 then
break
end
end
return Qnc,Rnc,Snc,Tnc
end
function gb.lockIds()
