function gb.lockTeam(doc,eoc,foc)
local goc=table.clone(doc)
local hoc={}
for ioc,joc in ipairs(goc)do
hoc[joc.unit_id]=true
end
local koc=N.session()
for loc in pairs(foc)do
if not hoc[loc]then
local moc
for noc,ooc in ipairs({eoc or{},(type(eoc)==G0e[2452]and eoc.rest)or{}})do
for poc,qoc in ipairs(ooc)do
if qoc.unit_id==loc then
moc=qoc
break
end
end
if moc then
break
end
end
if not moc and koc then
local roc
for soc,toc in pairs(koc.profile_data.collection.owned_units)do
if toc.unit_id==loc then
local uoc=koc.collection:get_unit_by_uuid(toc.uuid)or toc
local voc,woc=pcall(V.score,uoc)
woc=voc and tonumber(woc)or 0
if not roc or woc>roc then
moc,roc=uoc,woc
end
end
end
end
if moc then
local xoc
for yoc,zoc in ipairs(goc)do
if not foc[zoc.unit_id]and V.sameGroup(zoc.unit_id,loc)then
xoc=yoc
end
end
if not xoc and#goc<6 then
table.insert(goc,moc)
else
if not xoc then
local Aoc=0
for Boc,Coc in ipairs(goc)do
if V.isFarm(Coc.unit_id)then
Aoc=Aoc+1
end
end
local Doc
for Eoc,Foc in ipairs(goc)do
if not foc[Foc.unit_id]and not(V.isFarm(Foc.unit_id)and Aoc<=1)then
local Goc,Hoc=pcall(V.score,Foc)
Hoc=V.isFarm(Foc.unit_id)and math.huge or(Goc and tonumber(Hoc)or 0)
if not Doc or Hoc<Doc then
xoc,Doc=Eoc,Hoc
end
end
end
end
if xoc then
goc[xoc]=moc
end
end
hoc[loc]=true
end
end
end
return goc
end
function gb.bestTeam(Ioc,Joc,Koc,Loc)
