for mpc,opc in ipairs(Noc)do
if V.sameGroup(opc.unit_id,kpc.unit_id)then
lpc=true
end
end
if not lpc and(not ipc or V.isFarm(kpc.unit_id))then
local ppc=table.clone(Noc)
table.insert(ppc,kpc)
local qpc=gb.run(Ioc,gb.teamFrom(ppc,Ioc.map),{hpMul=Toc})
local rpc=gb.objective(qpc)
if not hpc or rpc>hpc then
gpc,hpc,fpc=kpc,rpc,qpc
end
end
end
if not gpc then
break
end
table.insert(Noc,gpc)
end
if _oc and Voc(Noc)==0 then
