for upc=1,#Noc do
for vpc,wpc in ipairs(Roc(Noc[upc])and{}or Koc)do
if V.isFarm(wpc.unit_id)then
local xpc=table.clone(Noc)
xpc[upc]=wpc
local ypc=gb.run(Ioc,gb.teamFrom(xpc,Ioc.map),{hpMul=Toc})
local zpc=gb.objective(ypc)
if not tpc or zpc>tpc then
spc,tpc,fpc=xpc,zpc,ypc
end
end
end
end
if spc then
Noc=spc
end
end
local function Apc(Bpc,Cpc)
