end
local Epc,Fpc=fpc or Uoc,Apc(Noc,fpc or Uoc)
if type(Koc.rest)==G0e[2452]and#Koc.rest>0 then
local Gpc,Hpc
for Ipc,Jpc in ipairs(Noc)do
if not V.isFarm(Jpc.unit_id)and not V.allyBuff(Jpc.unit_id)and not Roc(Jpc)then
local Kpc,Lpc=pcall(V.score,Jpc,Ioc.mod)
Lpc=(Kpc and Lpc or 0)*V.skinMul(Jpc,Ioc.skinSet)*V.eventMul(Jpc,Ioc.ld)
