if Gpc then
local Mpc,Npc={},U.now()
for Opc,Ppc in ipairs(Koc.rest)do
if U.now()-Npc>5 then
break
end
local Qpc=false
for Rpc,Spc in ipairs(Noc)do
if V.sameGroup(Spc.unit_id,Ppc.unit_id)then
Qpc=true
end
end
if not Qpc then
local Tpc=table.clone(Noc)
Tpc[Gpc]=Ppc
table.insert(Mpc,{u=Ppc,o=gb.objective(gb.run(Ioc,gb.teamFrom(Tpc,Ioc.map),{hpMul=Toc}))})
end
end
table.sort(Mpc,function(Upc,Vpc)
