local LIc=0
for MIc=2,#GIc do
local NIc,OIc=GIc[MIc-1],GIc[MIc]
local PIc=(OIc-NIc).Magnitude
local QIc=math.max(1,math.floor(PIc/2))
for RIc=0,QIc-1 do
local SIc=NIc:Lerp(OIc,RIc/QIc)
table.insert(bb.samples,{pos=SIc,prog=(LIc+PIc*RIc/QIc)/math.max(1,JIc),lane=EIc.Name})
end
LIc=LIc+PIc
end
if GIc[#GIc]then
table.insert(bb.samples,{pos=GIc[#GIc],prog=1,lane=EIc.Name})
end
end
end
pcall(bb.readHidden,DIc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
