function bb.barricadeOrder(Vdd,Wdd)
local Xdd,Ydd={},0
for Zdd,_dd in ipairs(Vdd or{})do
local aed=Vector3 .new(_dd.pos.X,0,_dd.pos.Z)
local bed,ced=0,math.huge
for ded,eed in ipairs(Wdd or{})do
local ged=(eed.p-aed).Magnitude
if ged<=eed.r then
bed=bed+1
end
if ged<ced then
ced=ged
end
end
if bed>Ydd then
Ydd=bed
end
table.insert(Xdd,{s=_dd,n=bed,d=ced})
end
if Ydd<1 then
return{}
end
local hed=Ydd>=2
local ied,jed={},{}
for ked,led in ipairs(Xdd)do
if(hed and led.n>=Ydd*bb.BARR_DENSE)or(not hed and led.n>=1)then
local med=tostring(led.s.lane)
if not ied[med]then
ied[med]={}
table.insert(jed,med)
end
table.insert(ied[med],led)
end
end
table.sort(jed)
local ned=0
for oed,ped in ipairs(jed)do
local qed=ied[ped]
if not hed then
table.sort(qed,function(sed,ted)
return(sed.s.prog or 0)<(ted.s.prog or 0)
end)
for ued=2,#qed do
if(qed[ued].s.prog or 0)-(qed[ued-1].s.prog or 0)>bb.BARR_GAP then
for ved= #qed,ued,-1 do
table.remove(qed,ved)
end
break
end
end
table.sort(qed,function(wed,xed)
if wed.d~=xed.d then
return wed.d<xed.d
end
return(wed.s.prog or 0)>(xed.s.prog or 0)
end)
else
table.sort(qed,function(yed,zed)
if yed.n~=zed.n then
return yed.n>zed.n
end
return(yed.s.prog or 0)>(zed.s.prog or 0)
end)
end
ned=math.max(ned,#qed)
end
local Aed={}
for Bed=1,ned do
for Ced,Ded in ipairs(jed)do
if ied[Ded][Bed]then
table.insert(Aed,ied[Ded][Bed].s.pos)
end
end
end
return Aed
end
function bb.defPick(Eed,Fed,Ged,Hed,Ied,Jed,Ked)
