end
elseif not Eid.done and cid-Eid.t>=15 then
Eid.done=true
local Kid=(Cid.prog-Eid.p)/(cid-Eid.t)/math.max(0.1,Eid.sp)
if Kid>0.001 and Cid.prog<0.95 then
table.insert(_hd.walk,Kid)
