bb.REAL_WIN=75
function bb.realK(ild)
local jld=bb.realC
local kld=U.now()
if not jld then
jld={t=0,k={},snaps={},seen={}}
bb.realC=jld
end
if kld-jld.t>=5 then
jld.t=kld
jld.k={}
local lld,mld,nld=pcall(bb.damageShares)
local pld={}
if lld and type(mld)==G0e[2452]and(nld or 0)>0 then
for qld,rld in pairs(mld)do
pld[qld]=rld*nld
end
end
local sld,tld={},0
for uld,vld in ipairs(bb.mine or{})do
local wld=vld:FindFirstChild(G0e[2524])
local xld=wld and wld:FindFirstChild(G0e[2845])and wld.id.Value
if xld and not V.isFarm(xld)then
local yld,zld=pcall(bb.liveDps,vld,xld)
zld=yld and tonumber(zld)or 0
sld[xld]=(sld[xld]or 0)+zld
tld=tld+zld
jld.seen[xld]=jld.seen[xld]or kld
end
end
table.insert(jld.snaps,{t=kld,abs=pld})
while#jld.snaps>1 and kld-jld.snaps[2].t>=bb.REAL_WIN do
table.remove(jld.snaps,1)
end
local Ald=jld.snaps[1]
if kld-Ald.t>=20 and tld>0 then
local Bld,Cld={},0
for Dld in pairs(sld)do
local Eld=math.max(0,(pld[Dld]or 0)-(Ald.abs[Dld]or 0))
Bld[Dld]=Eld
Cld=Cld+Eld
end
if Cld>0 then
local Fld
for Gld,Hld in pairs(sld)do
if kld-jld.seen[Gld]>=eb.REAL_AGE then
local Ild=eb.realK(Bld[Gld]/Cld,Hld/tld,eb.REAL_AGE)
if not Fld or Ild<Fld then
Fld=Ild
end
end
end
for Jld,Kld in pairs(sld)do
jld.k[Jld]=eb.realK(Bld[Jld]/Cld,Kld/tld,kld-jld.seen[Jld],Fld)
end
end
end
end
return jld.k[ild]or 1
end
