function bb.learn()
local jEd=bb.calRun and bb.calRun.potBy
if type(jEd)~=G0e[2452]then
return
end
pcall(bb.sampleHelpers,true)
local kEd={}
for lEd,mEd in pairs(bb.ownDealt or{})do
if not V.isFarm(mEd.id)then
kEd[mEd.id]=(kEd[mEd.id]or 0)+(tonumber(mEd.v)or 0)
end
end
for nEd,oEd in pairs(bb.helperDealt or{})do
if oEd.owner and V.SUMMONER[oEd.owner]and not V.droneHelper(oEd)then
kEd[oEd.owner]=(kEd[oEd.owner]or 0)+(tonumber(oEd.v)or 0)
end
end
local pEd=type(bb.calRun.potExp)==G0e[2452]and bb.calRun.potExp or{}
local qEd,rEd=0,0
local sEd={}
for tEd,uEd in pairs(jEd)do
if uEd>0 then
qEd,rEd=qEd+(kEd[tEd]or 0),rEd+uEd
local vEd=tonumber(pEd[tEd])or uEd
if vEd>0 then
table.insert(sEd,{id=tEd,r=(kEd[tEd]or 0)/vEd,w=vEd})
end
end
end
if qEd<=0 or rEd<=0 then
return
end
table.sort(sEd,function(wEd,xEd)
return wEd.r<xEd.r
end)
local function yEd(zEd)
local AEd,BEd=0,0
for CEd,DEd in ipairs(sEd)do
if DEd.id~=zEd then
AEd=AEd+DEd.w
end
end
if AEd<=0 then
return nil
end
for EEd,FEd in ipairs(sEd)do
if FEd.id~=zEd then
BEd=BEd+FEd.w
if BEd>=AEd/2 then
return FEd.r
end
end
end
end
bb.lastEff={}
for GEd,HEd in pairs(jEd)do
local IEd=yEd(GEd)
if HEd>0 and HEd/rEd>0.02 and IEd and IEd>0 then
local JEd=P.learn[GEd]or{eff=1,n=0,v=6}
V.learnUp(GEd,JEd)
local KEd=math.max(0.02,0.25*math.sqrt(30/(30+JEd.n)))
local LEd=U.clamp(((kEd[GEd]or 0)/HEd)/IEd,0.2,6)
bb.lastEff[GEd]=math.floor(LEd*1000+0.5)/1000
JEd.eff=JEd.eff+(LEd-JEd.eff)*KEd
JEd.n=JEd.n+1
P.learn[GEd]=JEd
end
end
local MEd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if MEd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==G0e[2452]and P.mapLearn or{}
local NEd=type(P.mapLearn[MEd])==G0e[2452]and P.mapLearn[MEd]or{}
for OEd,PEd in pairs(bb.lastEff)do
local QEd=type(NEd[OEd])==G0e[2452]and NEd[OEd]or{eff=PEd,n=0,v=6}
if(tonumber(QEd.v)or 0)<4 then
QEd.eff,QEd.v=(tonumber(QEd.eff)or PEd)*V.secRescale(OEd),4
end
if(tonumber(QEd.v)or 0)<5 then
QEd.eff,QEd.v=(tonumber(QEd.eff)or PEd)*(V.sumRescale(OEd)or 1),5
end
if(tonumber(QEd.v)or 0)<6 then
QEd.eff,QEd.v=(tonumber(QEd.eff)or PEd)*(1-(V.SUMMONER[OEd]and V.SUMMONER[OEd].droneShare or 0)),6
end
local REd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(QEd.n)or 0))))
QEd.eff=(tonumber(QEd.n)or 0)==0 and PEd or((tonumber(QEd.eff)or PEd)+(PEd-(tonumber(QEd.eff)or PEd))*REd)
QEd.n=(tonumber(QEd.n)or 0)+1
NEd[OEd]=QEd
end
NEd._at=os.time()
P.mapLearn[MEd]=NEd
if U.count(P.mapLearn)>80 then
local SEd,TEd
for UEd,VEd in pairs(P.mapLearn)do
if not TEd or(tonumber(VEd._at)or 0)<TEd then
SEd,TEd=UEd,tonumber(VEd._at)or 0
end
end
P.mapLearn[SEd]=nil
end
end
end
