function bb.baseVerdict(cLd,dLd)
local eLd=(dLd.t or 0)-(cLd.t or 0)
if eLd<bb.BASE_WIN-1 then
return false
end
local fLd=((tonumber(cLd.base)or 0)-(tonumber(dLd.base)or 0))/eLd
if fLd<=0 or(tonumber(dLd.base)or 0)<=0 then
return false
end
local gLd=dLd.base/fLd
local hLd,iLd=0,0
local jLd,kLd=cLd.foes or{},dLd.foes or{}
for lLd,mLd in pairs(kLd)do
if mLd.prog>=bb.BASE_END then
hLd=hLd+mLd.hp
local nLd=jLd[lLd]
if nLd then
iLd=iLd+math.max(0,nLd.hp-mLd.hp)
end
end
end
for oLd,pLd in pairs(jLd)do
if pLd.prog>=bb.BASE_END and not kLd[oLd]then
iLd=iLd+pLd.hp
end
end
if hLd<=0 then
return false
end
local qLd=iLd/eLd
local rLd=qLd>0 and hLd/qLd or math.huge
local sLd={baseTime=gLd,loss=fLd,atEnd=hLd,rate=qLd,killTime=rLd}
return gLd<bb.BASE_SOON and rLd>gLd*bb.BASE_MARGIN,sLd
end
